class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

class CQuadWorkspace:
    def __init__(self, workspace_size):
        self.workspace_size = workspace_size
        self.workspace = ctypes.c_void_p()
        self.result = ctypes.c_double()
        self.abserr = ctypes.c_double()
        self.neval = ctypes.c_long()

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    gsl_function = GSLFunction(func)
    workspace = CQuadWorkspace(workspace_size)
    status = gsl.gsl_integration_cquad(ctypes.pointer(gsl_function), ctypes.c_double(a), ctypes.c_double(b), ctypes.c_double(epsabs), ctypes.c_double(epsrel), workspace.workspace, ctypes.byref(workspace.result), ctypes.byref(workspace.abserr), ctypes.byref(workspace.neval))
    if status != 0:
        raise Exception("GSL integration failed with error %d" % (status,))
    return workspace.result.value, workspace.abserr.value, workspace.neval.value

def my_func(x):
    return x**2 + 1

