def prime_factors(n):
    num = ctypes.c_int(n)
    factors = ctypes.POINTER(ctypes.c_int)()
    cnt = ctypes.c_size_t()
    gsl.gsl_factorize(num, ctypes.byref(factors), ctypes.byref(cnt))
    return list(map(lambda x: int(x.value), factors[0:cnt.value]))

def fft_factorize(n):
    gsl = load_gsl()
    subtransforms = [ctypes.c_int(2), ctypes.c_int(3), ctypes.c_int(5)]
    prime_factors = []
    for transform in subtransforms:
        prime_factors += prime_factors(n)
    return prime_factors

