def process_array(input_array):
    try:
        # Load the GSL library if it's not already loaded
        gsl = load_gsl()["gsl"]

        # Create a pointer to the input array
        input_ptr = (ctypes.c_double * len(input_array))(*input_array)

        # Create a pointer to the output array
        output_ptr = (ctypes.POINTER(ctypes.c_double) * len(input_array))()

        # Call the GSL function that performs the mathematical operation on the input array
        gsl.process_array(input_ptr, ctypes.c_int(len(input_array)), output_ptr)

        # Extract the output from the pointer
        output = [float(output_ptr[i]) for i in range(len(input_array))]

