gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLVector(object):
    def __init__(self, size):
        self.size = size
        self.data = (ctypes.c_double * size)()

    def get_data(self):
        return self.data

    def set_data(self, data):
        for i in range(self.size):
            self.data[i] = ctypes.c_double(data[i])

class GSLRng(object):
    def __init__(self):
        self.rng = gsl.gsl_rng_alloc()

    def set_seed(self, seed):
        gsl.gsl_rng_set(self.rng, ctypes.c_uint(seed))

class GSLFilterGaussianWorkspace(object):
    def __init__(self):
        self.workspace = gsl.gsl_filter_gaussian_alloc()

def gaussian_filter(vector, workspace):
    size = vector.size
    output = np.zeros(size)
    for i in range(size):
        output[i] = ctypes.c_double(0)
    gsl.gsl_filter_gaussian_forward(vector.get_data(), ctypes.c_size_t(size), workspace, output, ctypes.c_size_t(2))
    return output

def first_derivative(vector):
    size = vector.size
    output = np.zeros(size)
    for i in range(size):
        output[i] = ctypes.c_double(0)
    gsl.gsl_filter_gaussian_forward_diff(vector.get_data(), ctypes.c_size_t(size), output, ctypes.c_size_t(2))
    return output

def second_derivative(vector):
    size = vector.size
    output = np.zeros(size)
    for i in range(size):
        output[i] = ctypes.c_double(0)
    gsl.gsl_filter_gaussian_forward_diff2(vector.get_data(), ctypes.c_size_t(size), output, ctypes.c_size_t(2))
    return output

def print_results(input_vector, smoothed_values, derivatives):
    size = input_vector.size
    for i in range(size):
        print("xi:", input_vector[i], "yi:", smoothed_values[i], "dxi:", derivatives[i])

def main():
    N = int(input()) # size of the vector
    alpha = float(input()) # filter parameter

    rng = GSLRng()
    rng.set_seed(10) # set seed for reproducibility

    workspace = GSLFilterGaussianWorkspace()
    workspace.workspace.alpha = ctypes.c_double(alpha)

    input_vector = GSLVector(N)
    for i in range(N):
        xi = np.random.uniform(-1, 1) # random values for input vector
        ei = np.random.normal() # add some noise to the input vector
        input_vector[i] = ctypes.c_double(xi + ei)

