    _fields_ = [("size1", ctypes.c_size_t), ("size2", ctypes.c_size_t), ("tda", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

class gsl_vector(ctypes.Structure):
    _fields_ = [("size", ctypes.c_size_t), ("stride", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

class gsl_eigen_gensymm_workspace(ctypes.Structure):
    _fields_ = [("dim", ctypes.c_size_t), ("max_iterations", ctypes.c_int), ("tolerance", ctypes.c_double)]

def numpy_to_gsl_matrix(np_array):
    if np_array.ndim != 2:
        raise ValueError("numpy array must be two-dimensional")
    gsl_matrix = gsl.gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            gsl_matrix.data[i * np_array.strides[0] + j * np_array.strides[1]] = np_array[i, j]
    return gsl_matrix

def numpy_to_gsl_vector(np_array):
    if np_array.ndim != 1:
        raise ValueError("numpy array must be one-dimensional")
    gsl_vector = gsl.gsl_vector_alloc(np_array.shape[0])
    for i in range(np_array.shape[0]):
        gsl_vector.data[i * np_array.strides[0]] = np_array[i]
    return gsl_vector

def compute_gensymm_eigenvalues(A, B):
    if A.shape != B.shape:
        raise ValueError("input matrices must have the same dimensions")
    workspace = gsl_eigen_gensymm_workspace()
    workspace.dim = A.shape[0]
    eigenvalues = np.zeros((A.shape[0],))
    for i in range(A.shape[0]):
        gsl_matrix = numpy_to_gsl_matrix(A)
        gsl_vector = numpy_to_gsl_vector(B)
        result = gsl_cblas.gsl_eigen_gensymm_alloc(workspace.dim)
        gsl_cblas.gsl_eigen_gensymm_evalsx(result, gsl_matrix, gsl_vector, workspace)
        for j in range(A.shape[0]):
            eigenvalues[j] = result.data[i * A.strides[0] + j * A.strides[1]]
    return eigenvalues

