def compute_eigen(matrix, size):
    # Create gsl_matrix_complex and gsl_vector objects
    matrix_obj = GSLMatrixComplex(matrix)
    vector_obj = GSLVector(GSLVector([0] * size))

    # Allocate workspace for eigen decomposition
    workspace_obj = GSLEigenHermvWorkspace(size)

