class gsl_vector(ctypes.Structure):
    _fields_ = [("data", ctypes.POINTER(ctypes.c_float)), ("stride", ctypes.c_size_t), ("size", ctypes.c_size_t)]

gsl_linalg_hessenberg_decomp = gsl.CDLL("gsl_linalg_hessenberg_decomp")
gsl_linalg_hessenberg_decomp.restype = None
gsl_linalg_hessenberg_decomp.argtypes = [gsl_matrix, gsl_vector]

def hessenberg_decomp(matrix: list[list[float]], tau: list[float]) -> tuple[list[list[float]], list[float]]:
    matrix = gsl_matrix(ctypes.c_float * len(matrix) * len(matrix[0]), (len(matrix), len(matrix[0])))
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            matrix[i, j] = matrix[i][j]
    tau = gsl_vector(ctypes.c_float * len(tau), (len(tau), 1))

