class cblas_scopy(ctypes.Structure):
    _fields_ = [("N", ctypes.c_int), ("X", POINTER(ctypes.c_float)), ("incX", ctypes.c_int), ("Y", POINTER(ctypes.c_float)), ("incY", ctypes.c_int)]

def copy_float_array(N, X, incX, Y, incY):
    cblas_scopy = gslcblas.cblas_scopy
    cblas_scopy.argtypes = [ctypes.c_int, POINTER(ctypes.c_float), ctypes.c_int, POINTER(ctypes.c_float), ctypes.c_int]
    cblas_scopy.restype = None
    X_ptr = (ctypes.c_float * len(X)).from_buffer(bytearray(X))
    Y_ptr = (ctypes.c_float * len(Y)).from_buffer(bytearray(Y))
    cblas_scopy(N, X_ptr, incX, Y_ptr, incY)
    return Y

