import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.gsl_matrix = self._matrix_to_gsl(matrix)

    def _matrix_to_gsl(self, matrix):
        # Load the dynamic libraries for GSL
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Create a GSL matrix from the input matrix
        gsl_matrix = np.array(self.matrix, dtype=np.float64).reshape(-1)
        gsl_matrix = gsl.gsl_matrix_alloc(len(gsl_matrix), len(gsl_matrix))
        for i in range(len(gsl_matrix)):
            for j in range(len(gsl_matrix[i])):
                gsl_matrix[i][j] = matrix[i][j]

        return gsl_matrix

    def gsl_matrix_to_numpy(self, gsl_matrix):
        # Convert the GSL matrix back to a NumPy array
        numpy_array = np.array(gsl_matrix)
        return numpy_array.reshape((len(gsl_matrix), len(gsl_matrix)))

    def compute_matrix_exponential(self, mode):
        # Compute the matrix exponential using GSL
        gsl_matrix = self._matrix_to_gsl(self.matrix)
        result = gsl.gsl_linalg_exponential_ss(gsl_matrix, mode)
        return self.gsl_matrix_to_numpy(result)

