libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def bspline_wlssolve(x, y, weights):
    gsl_vector = ctypes.POINTER(ctypes.c_double) * len(y)

    x_ptr = (gsl_vector*len(x))()
    for i in range(len(x)):
        x_ptr[i] = ctypes.cast(ctypes.pointer(ctypes.c_double(x[i])), gsl_vector)

    y_ptr = (gsl_vector*len(y))()
    for i in range(len(y)):
        y_ptr[i] = ctypes.cast(ctypes.pointer(ctypes.c_double(y[i])), gsl_vector)

    weights_ptr = None
    if weights is not None:
        weights_ptr = (gsl_vector*len(weights))()
        for i in range(len(weights)):
            weights_ptr[i] = ctypes.cast(ctypes.pointer(ctypes.c_double(weights[i])), gsl_vector)

    workspace = gsl.gsl_bspline_workspace()
    solution = gsl.gsl_bspline_wlssolve(x_ptr, y_ptr, weights_ptr, len(y), 3, workspace)

    coefficients = []
    for i in range(solution.num):
        coefficients.append(ctypes.c_double(solution.coefficients[i]))

    chi_squared = ctypes.c_double(solution.chi_squared)

    return coefficients, chi_squared

def solve(x, y, weights):
    try:
        coefficients, chi_squared = bspline_wlssolve(x, y, weights)
        result = { "Candidate_solution": json.dumps([coefficients, chi_squared]) }
        return result
    except Exception as e:
        print("Exception occurred:", e)
        return {}

