def matrix_to_gsl(matrix):
    gsl_matrix = gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            gsl_matrix[i,j] = matrix[i][j]
    return gsl_matrix

def vector_to_gsl(vector):
    gsl_vector = gsl.gsl_vector_alloc(len(vector))
    for i in range(len(vector)):
        gsl_vector[i] = vector[i]
    return gsl_vector

def gsl_matrix_to_list(gsl_matrix):
    matrix = []
    for i in range(gsl_matrix.size1):
        row = []
        for j in range(gsl_matrix.size2):
            row.append(gsl_matrix[i,j])
        matrix.append(row)
    return matrix

def gsl_vector_to_list(gsl_vector):
    vector = []
    for i in range(gsl_vector.size):
        vector.append(gsl_vector[i])
    return vector

def ql_decomposition_and_unpack(A, tau):
    gsl_matrix = matrix_to_gsl(A)
    gsl_vector = vector_to_gsl(tau)
    gsl.gsl_linalg_QL_decomp(gsl_matrix, gsl_vector)
    Q = gsl_matrix_to_list(gsl_matrix)
    L = gsl_matrix_to_list(gsl.gsl_matrix_alloc(len(Q), len(Q[0])))
    for i in range(len(L)):
        for j in range(i, len(L[0])):
            L[i][j] = Q[i][j]
    return (Q, L)

def main():
    A = [[1, 2], [3, 4]]
    tau = [5, 6]
    result = ql_decomposition_and_unpack(A, tau)
    Q, L = result
    return json.dumps({"Candidate_solution": str(Q) + "\n" + str(L)})

if __name__ == "__main__":
