def cholesky(matrix):
    # Load the necessary dynamic libraries
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the GSLMatrix class
    class GSLMatrix:
        def __init__(self, matrix):
            self.matrix = matrix
            self.nrows = len(matrix)
            self.ncols = len(matrix[0]) if matrix else 0

        def get_gsl_matrix(self):
            gsl_matrix = gsl.gsl_matrix_alloc(self.nrows, self.ncols)
            for i in range(self.nrows):
                for j in range(self.ncols):
                    gsl_matrix[i][j] = self.matrix[i][j]
            return gsl_matrix

    # Check if the input matrix is positive definite
    if not GSLMatrix(matrix).is_positive_definite():
        raise ValueError("Input matrix must be positive definite")

    # Perform Cholesky decomposition using GSL
    cholesky = gsl.gsl_linalg_cholesky_decomp(GSLMatrix(matrix).get_gsl_matrix())

    # Convert the resulting lower triangular matrix to a list of lists
    result = []
    for i in range(cholesky.size1):
        row = []
        for j in range(cholesky.size2):
            row.append(cholesky[i][j])
        result.append(row)

    # Free the GSL memory
    gsl.gsl_matrix_free(cholesky)

    return {"Candidate_solution": str(result)}

